DROP VIEW IF EXISTS view__cksap;
--
CREATE VIEW view__cksap AS
SELECT
	Исходник,"Строка в исходнике","Дата отправления","Дата прибытия","Номер вагона","Номер контейнера","Номер накладной",Футовость,
	'фитинговая платформа' AS Родвагона,
	"Вид спецконтейнера","Груж-пор","Государство отправления","Государство назначения","Код станции отправления РФ","Название станции отправления РФ","Код станции назначения РФ","Название станции назначения РФ","Код станции отправления СНГ","Код станции назначения СНГ","Дорога отпр","Дорога наз","Вид перевозки","Код Груза ЕТСНГ","Название Груза ЕТСНГ","Группа груза","Код груза ГНГ",Грузоотправитель,ГрузоотправительГруппа,Грузополучатель,ГрузополучательГруппа,Плательщик,ПлательщикГруппа,Собственник,СобственникГруппа,Арендатор,АрендаторГруппа,Оператор,ОператорГруппа,КолВоКонт,ДФЭ,"Вес груза"
FROM raw_cksap_fitingi
UNION DISTINCT
SELECT
	Исходник,"Строка в исходнике","Дата отправления","Дата прибытия","Номер вагона","Номер контейнера","Номер накладной",Футовость,
	Родвагона,
	"Вид спецконтейнера","Груж-пор","Государство отправления","Государство назначения","Код станции отправления РФ","Название станции отправления РФ","Код станции назначения РФ","Название станции назначения РФ","Код станции отправления СНГ","Код станции назначения СНГ","Дорога отпр","Дорога наз","Вид перевозки","Код Груза ЕТСНГ","Название Груза ЕТСНГ","Группа груза","Код груза ГНГ",Грузоотправитель,ГрузоотправительГруппа,Грузополучатель,ГрузополучательГруппа,Плательщик,ПлательщикГруппа,Собственник,СобственникГруппа,Арендатор,АрендаторГруппа,Оператор,ОператорГруппа,КолВоКонт,ДФЭ,"Вес груза"
FROM raw_cksap_krytye
UNION DISTINCT
SELECT
	Исходник,"Строка в исходнике","Дата отправления","Дата прибытия","Номер вагона","Номер контейнера","Номер накладной",Футовость,
	Родвагона,
	"Вид спецконтейнера","Груж-пор","Государство отправления","Государство назначения","Код станции отправления РФ","Название станции отправления РФ","Код станции назначения РФ","Название станции назначения РФ","Код станции отправления СНГ","Код станции назначения СНГ","Дорога отпр","Дорога наз","Вид перевозки","Код Груза ЕТСНГ","Название Груза ЕТСНГ","Группа груза","Код груза ГНГ",Грузоотправитель,ГрузоотправительГруппа,Грузополучатель,ГрузополучательГруппа,Плательщик,ПлательщикГруппа,Собственник,СобственникГруппа,Арендатор,АрендаторГруппа,Оператор,ОператорГруппа,КолВоКонт,ДФЭ,"Вес груза"
FROM raw_cksap_poluvagony_gruzhionye
UNION DISTINCT
SELECT
	Исходник,"Строка в исходнике","Дата отправления","Дата прибытия","Номер вагона","Номер контейнера","Номер накладной",Футовость,
	Родвагона,
	"Вид спецконтейнера","Груж-пор","Государство отправления","Государство назначения","Код станции отправления РФ","Название станции отправления РФ","Код станции назначения РФ","Название станции назначения РФ","Код станции отправления СНГ","Код станции назначения СНГ","Дорога отпр","Дорога наз","Вид перевозки","Код Груза ЕТСНГ","Название Груза ЕТСНГ","Группа груза","Код груза ГНГ",Грузоотправитель,ГрузоотправительГруппа,Грузополучатель,ГрузополучательГруппа,Плательщик,ПлательщикГруппа,Собственник,СобственникГруппа,Арендатор,АрендаторГруппа,Оператор,ОператорГруппа,КолВоКонт,ДФЭ,"Вес груза"
FROM raw_cksap_poluvagony_porozhnie;